{"code":"import json
import numpy as np
import pandas as pd

with open("evaluations.json") as f:
    data = json.load(f)

rows = []
for d in data:
    r = {x["ingredient"]: x["fraction"] for x in d["recipe"]}
    rows.append(r)

df = pd.DataFrame(rows).fillna(0)
X = df.values
y = np.array([d["target_dissimilarity"] for d in data])

for i in range(len(data)):
    for j in range(i+1, len(data)):
        l2 = np.linalg.norm(X[i] - X[j])
        l1 = np.sum(np.abs(X[i] - X[j]))
        if l2 < 0.4:
            print(f"Iter {i+1} (y={y[i]:.4f}) <-> Iter {j+1} (y={y[j]:.4f}): L2={l2:.4f}, L1={l1:.4f}")
"}

